CREATE TABLE "InventoryItem" ("id" UUID NOT NULL, "hospitalId" UUID NOT NULL, "name" TEXT NOT NULL, "type" "InventoryItemType" NOT NULL, "category" TEXT, "quantity" INTEGER NOT NULL DEFAULT 0, "reorderLevel" INTEGER NOT NULL DEFAULT 0, "unitCost" DECIMAL(12,2), "location" TEXT, "status" "InventoryItemStatus" NOT NULL DEFAULT 'ACTIVE', "supplierName" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InventoryItem_pkey" PRIMARY KEY ("id"));
