CREATE TABLE "Receipt" ("id" UUID NOT NULL, "hospitalId" UUID NOT NULL, "invoiceId" UUID NOT NULL, "receiptNumber" TEXT NOT NULL, "amount" DECIMAL(12,2) NOT NULL, "issuedById" UUID NOT NULL, "issuedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Receipt_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Receipt_hospitalId_receiptNumber_key" ON "Receipt"("hospitalId", "receiptNumber");
CREATE UNIQUE INDEX "Receipt_hospitalId_invoiceId_key" ON "Receipt"("hospitalId", "invoiceId");
