CREATE TABLE "PayrollIntegration" ("id" UUID NOT NULL, "hospitalId" UUID NOT NULL, "providerName" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'CONFIGURED', "configuration" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PayrollIntegration_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PayrollIntegration_hospitalId_providerName_key" ON "PayrollIntegration"("hospitalId", "providerName");
CREATE TABLE "Reminder" ("id" UUID NOT NULL, "hospitalId" UUID NOT NULL, "userId" UUID, "type" "ReminderType" NOT NULL, "status" "ReminderStatus" NOT NULL DEFAULT 'SCHEDULED', "subject" TEXT NOT NULL, "body" TEXT NOT NULL, "runAt" TIMESTAMP(3) NOT NULL, "backgroundJobId" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Reminder_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Reminder_backgroundJobId_key" ON "Reminder"("backgroundJobId");
